pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        vm.assume(msg.sender != address(c).owner); // ensure constructor sends XBornID to actual owner
    }
    function testFuzz_property(address newOwner) public {
        // The fuzzer explores whether transferring ownership or any action changes the invariant
        // that balances[owner] should equal totalDistributed, not totalSupply.
        // We drive through XBornID() which is called in constructor; ownership transfer is allowed
        // but does not alter existing balances.
        if (newOwner != address(0)) {
            vm.prank(c.owner());
            c.transferOwnership(newOwner);
        }
        // Assert the general invariant: the owner's balance must be totalDistributed (the correct initial value).
        // The buggy version sets it to totalSupply, so this assertion fails for any run.
        assertTrue(c.balanceOf(c.owner()) == c.totalDistributed());
    }
}

