pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address holder, uint256 amount) public {
        vm.assume(holder != address(0));
        vm.assume(amount <= type(uint256).max - c.totalDistributed());
        // Transfer any amount to the holder to check sum consistency
        if (holder != address(c).balance) {
            vm.prank(address(c).balance);
            bool success = c.transfer(holder, amount);
            require(success);
        }
        // Compute sum of balances: only owner is non-zero initially, but after transfer also holder
        uint256 totalBalance = c.balanceOf(address(c).balance) + c.balanceOf(holder);
        assertTrue(totalBalance == c.totalDistributed());
    }
}

