contract InvMutTest {
    C c;
    constructor(C _c) public {
        c = _c;
    }
    function test(address newOwner) public returns (bool) {
        require(newOwner != address(0));
        c.transferOwnership(newOwner);
        c.finishDistribution();
        uint256 supply = c.totalSupply();
        uint256 distributed = c.totalDistributed();
        uint256 remaining = c.totalRemaining();
        uint256 ownerBal = c.balanceOf(newOwner);
        assert(supply == distributed + remaining + ownerBal);
        return true;
    }
}

